export function getTerritoryById(territoryId: string): TerritoryRegionDefinition | undefined {
  return GLOBAL_TERRITORY_CATALOG.find(t => t.territoryId === territoryId);
}

export function getTerritoriesByMacroRegion(macroRegionCode: string): TerritoryRegionDefinition[] {
  return GLOBAL_TERRITORY_CATALOG.filter(t => t.macroRegionCode === macroRegionCode);
}